-- Migration 001: repeatable, transactional bootstrap (SQLite 3).
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
INSERT OR IGNORE INTO schema_migrations VALUES(1,datetime('now'));
CREATE TABLE IF NOT EXISTS tenants(id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, settings TEXT NOT NULL, demo INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), email TEXT NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','agent')), password_hash TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, UNIQUE(tenant_id,email));
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS leads(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), name TEXT NOT NULL, phone TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', source TEXT NOT NULL, external_id TEXT NOT NULL DEFAULT '', stage TEXT NOT NULL DEFAULT 'New', budget REAL NOT NULL DEFAULT 0, location TEXT NOT NULL DEFAULT '', property_type TEXT NOT NULL DEFAULT '', intent TEXT NOT NULL DEFAULT 'buy', bedrooms INTEGER NOT NULL DEFAULT 0, min_size REAL NOT NULL DEFAULT 0, amenities TEXT NOT NULL DEFAULT '[]', score INTEGER NOT NULL DEFAULT 0, assigned_to TEXT NOT NULL DEFAULT '', consent INTEGER NOT NULL DEFAULT 0, opted_out INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS lead_phone ON leads(tenant_id,phone) WHERE phone<>'';
CREATE UNIQUE INDEX IF NOT EXISTS lead_email ON leads(tenant_id,email) WHERE email<>'';
CREATE UNIQUE INDEX IF NOT EXISTS lead_external ON leads(tenant_id,source,external_id) WHERE external_id<>'';
CREATE INDEX IF NOT EXISTS lead_tenant ON leads(tenant_id,updated_at);
CREATE TABLE IF NOT EXISTS properties(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), title TEXT NOT NULL, location TEXT NOT NULL, property_type TEXT NOT NULL, intent TEXT NOT NULL, price REAL NOT NULL, size REAL NOT NULL, bedrooms INTEGER NOT NULL, amenities TEXT NOT NULL DEFAULT '[]', status TEXT NOT NULL DEFAULT 'Available', description TEXT NOT NULL DEFAULT '', image TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), lead_id TEXT NOT NULL REFERENCES leads(id) ON DELETE CASCADE, direction TEXT NOT NULL, channel TEXT NOT NULL, body TEXT NOT NULL, external_id TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS message_external ON messages(tenant_id,channel,external_id) WHERE external_id<>'';
CREATE TABLE IF NOT EXISTS appointments(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), lead_id TEXT NOT NULL REFERENCES leads(id) ON DELETE CASCADE, property_id TEXT NOT NULL REFERENCES properties(id), agent_id TEXT NOT NULL REFERENCES users(id), start_at TEXT NOT NULL, end_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Booked', notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS appointment_slots ON appointments(tenant_id,agent_id,start_at,end_at);
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), lead_id TEXT REFERENCES leads(id) ON DELETE CASCADE, title TEXT NOT NULL, due_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Pending', kind TEXT NOT NULL DEFAULT 'followup', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS deals(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), lead_id TEXT NOT NULL REFERENCES leads(id) ON DELETE CASCADE, property_id TEXT REFERENCES properties(id), amount REAL NOT NULL, commission REAL NOT NULL DEFAULT 0, status TEXT NOT NULL, lost_reason TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS activities(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), actor TEXT NOT NULL, action TEXT NOT NULL, entity_id TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS outbox(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), lead_id TEXT NOT NULL REFERENCES leads(id) ON DELETE CASCADE, channel TEXT NOT NULL, body TEXT NOT NULL, template TEXT NOT NULL DEFAULT '', dedupe_key TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Pending', attempts INTEGER NOT NULL DEFAULT 0, next_attempt TEXT NOT NULL, external_id TEXT NOT NULL DEFAULT '', error TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, UNIQUE(tenant_id,dedupe_key));
CREATE TABLE IF NOT EXISTS webhook_events(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), channel TEXT NOT NULL, external_id TEXT NOT NULL, received_at TEXT NOT NULL, UNIQUE(tenant_id,channel,external_id));
CREATE TABLE IF NOT EXISTS chat_sessions(token_hash TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), lead_id TEXT NOT NULL REFERENCES leads(id) ON DELETE CASCADE, created_at TEXT NOT NULL);
-- Migration 002 adds operational controls without rewriting existing business tables.
CREATE TABLE IF NOT EXISTS conversation_controls(lead_id TEXT PRIMARY KEY REFERENCES leads(id) ON DELETE CASCADE, tenant_id TEXT NOT NULL REFERENCES tenants(id), human_active INTEGER NOT NULL DEFAULT 0, reason TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS consent_events(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), lead_id TEXT NOT NULL REFERENCES leads(id) ON DELETE CASCADE, granted INTEGER NOT NULL, actor TEXT NOT NULL, evidence TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS automation_receipts(tenant_id TEXT NOT NULL REFERENCES tenants(id), event_id TEXT NOT NULL, request_hash TEXT NOT NULL, result TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(tenant_id,event_id));
CREATE TABLE IF NOT EXISTS incidents(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), event_id TEXT NOT NULL, workflow_id TEXT NOT NULL, execution_id TEXT NOT NULL, category TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Open', created_at TEXT NOT NULL, UNIQUE(tenant_id,event_id));
INSERT OR IGNORE INTO schema_migrations VALUES(2,datetime('now'));
